#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gramschmidt.h"

/* 
 * Blocking factor for the j-dimension of the trailing matrix update.
 * Chosen to improve cache locality and allow the compiler to generate
 * efficient vectorized code over the innermost j loops.
 */
#define J_BLOCK_SIZE 32


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j;

  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      A[i][j] = (((DATA_TYPE) ((i*j) % m) / m )*100) + 10;
      Q[i][j] = 0.0;
    }
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      R[i][j] = 0.0;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("R");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, R[i][j]);
    }
  POLYBENCH_DUMP_END("R");

  POLYBENCH_DUMP_BEGIN("Q");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, Q[i][j]);
    }
  POLYBENCH_DUMP_END("Q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* QR Decomposition with Modified Gram Schmidt:
   http://www.inf.ethz.ch/personal/gander/ */

/*
 * Optimized kernel:
 *
 * - Uses local restrict-qualified pointers A_, R_, Q_ to give the compiler
 *   better aliasing information, which helps auto-vectorization.
 *
 * - The original algorithm processes each column j>k of the trailing
 *   matrix one at a time:
 *       R[k][j] = Q[:,k]^T * A[:,j]
 *       A[:,j]  = A[:,j] - Q[:,k] * R[k][j]
 *
 *   That pattern accesses A and Q with a large stride in memory (i is
 *   inner loop, j is outer), which is unfriendly to caches and SIMD.
 *
 * - We instead process the trailing columns in small j-blocks. For a given
 *   k and a block of columns j in [jb, j_end):
 *     1) We compute all dot products R[k][j] (for the whole block) using
 *        A and Q, keeping partial sums in a small stack array r_block[].
 *     2) We write the completed R[k][j] values to R.
 *     3) We update A[:, j] for the whole block using those R values.
 *
 *   Within each block, we iterate over i (rows) outside and j (columns)
 *   inside, so A[i][jb..j_end) is accessed contiguously in memory.  The
 *   order of floating-point operations for each individual R[k][j] sum
 *   over i is preserved: contributions are accumulated in increasing i,
 *   exactly as in the original code. A[i][j] is still updated once using
 *   the same Q[i][k] and R[k][j] as before. Thus, the mathematical
 *   semantics (and per-element operation order for each reduction) are
 *   preserved.
 */
static
void kernel_gramschmidt[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;
  (void)j; /* j is kept to preserve the original signature; avoid warnings. */

  DATA_TYPE nrm;

  /* Local restrict-qualified aliases to help the compiler with
     alias analysis and enable more aggressive vectorization. */
  DATA_TYPE (* restrict A_)[n] = A;
  DATA_TYPE (* restrict R_)[n] = R;
  DATA_TYPE (* restrict Q_)[n] = Q;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      /* Compute the 2-norm of column k of A. */
      nrm = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE aik = A_[i][k];
          nrm += aik * aik;
        }

      /* Normalize column k to obtain Q[:,k]. */
      R_[k][k] = SQRT_FUN(nrm);
      const DATA_TYPE Rkk = R_[k][k];
      for (i = 0; i < _PB_M; i++)
        Q_[i][k] = A_[i][k] / Rkk;

      /* Process the remaining columns j>k in cache-friendly j-blocks. */
      for (int jb = k + 1; jb < _PB_N; jb += J_BLOCK_SIZE)
        {
          const int j_end       = (jb + J_BLOCK_SIZE < _PB_N) ? (jb + J_BLOCK_SIZE) : _PB_N;
          const int block_width = j_end - jb;

          /* Partial sums for R[k][j] over this block of columns. */
          DATA_TYPE r_block[J_BLOCK_SIZE];

          /* Initialize partial dot products for all j in the block. */
          for (int jj = 0; jj < block_width; ++jj)
            r_block[jj] = SCALAR_VAL(0.0);

          /* Compute R[k][j] = sum_i Q[i][k] * A[i][j] for j in [jb, j_end). */
          for (i = 0; i < _PB_M; i++)
            {
              const DATA_TYPE qik = Q_[i][k];
              const DATA_TYPE *a_row = &A_[i][jb]; /* A[i][jb .. j_end-1] is contiguous */

              for (int jj = 0; jj < block_width; ++jj)
                r_block[jj] += qik * a_row[jj];
            }

          /* Store the completed R[k][j] values for this block. */
          for (int jj = 0; jj < block_width; ++jj)
            R_[k][jb + jj] = r_block[jj];

          /* Update A[i][j] = A[i][j] - Q[i][k] * R[k][j] for the same block. */
          for (i = 0; i < _PB_M; i++)
            {
              const DATA_TYPE qik = Q_[i][k];
              DATA_TYPE *a_row = &A_[i][jb]; /* A[i][jb .. j_end-1] */

              for (int jj = 0; jj < block_width; ++jj)
                a_row[jj] = a_row[jj] - qik * R_[k][jb + jj];
            }
        }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(R,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(Q,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(R),
	      POLYBENCH_ARRAY(Q));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gramschmidt (m, n,
		      POLYBENCH_ARRAY(A),
		      POLYBENCH_ARRAY(R),
		      POLYBENCH_ARRAY(Q));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(R), POLYBENCH_ARRAY(Q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(R);
  POLYBENCH_FREE_ARRAY(Q);

  return 0;
}
