/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* QR Decomposition with Modified Gram Schmidt:
   http://www.inf.ethz.ch/personal/gander/ */
static
void kernel_gramschmidt[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE nrm;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      /* ------------------------------------------------------------
       * 1) Compute the Euclidean norm of column k of A
       * ------------------------------------------------------------ */
      nrm = SCALAR_VAL(0.0);

      for (i = 0; i < _PB_M; i++)
      {
        /* Access A column-wise here; unavoidable for this algorithm. */
        DATA_TYPE Aik = A[i][k];
        nrm += Aik * Aik;
      }

      DATA_TYPE rkk = SQRT_FUN(nrm);
      R[k][k] = rkk;

      /* Precompute the reciprocal once and use a multiplication for
       * each element of Q instead of a division. This replaces M
       * divisions with M multiplications for better throughput. */
      DATA_TYPE inv_rkk = SCALAR_VAL(1.0) / rkk;

      /* ------------------------------------------------------------
       * 2) Normalize column k of A into column k of Q
       *    Q[i][k] = A[i][k] / R[k][k]
       * ------------------------------------------------------------ */
      for (i = 0; i < _PB_M; i++)
        Q[i][k] = A[i][k] * inv_rkk;

      /* Pointer to the k-th row of R.
       * Keeping this in a local pointer improves cache locality
       * and lets the compiler generate simpler addressing. */
      DATA_TYPE * restrict Rk = R[k];

      /* ------------------------------------------------------------
       * 3) Compute R[k][j] = dot(Q[:,k], A[:,j]) for j > k
       *
       * Original code:
       *   for (j = k+1; j < N; ++j) {
       *     R[k][j] = 0;
       *     for (i = 0; i < M; ++i)
       *       R[k][j] += Q[i][k] * A[i][j];
       *   }
       *
       * We keep the mathematical computation identical but change the
       * loop order to improve spatial locality:
       *
       *   - j is the inner loop: we walk A[i][j] and R[k][j] along the
       *     contiguous (row-major) dimension.
       *   - For each i we load Q[i][k] once and reuse it for all j>k.
       *
       * The order of additions for each fixed j is still by increasing i,
       * so the per-element reduction order is unchanged.
       * ------------------------------------------------------------ */

      /* Initialize R[k][j] = 0 for j > k
       * (R is upper triangular; indices j <= k are untouched here). */
      for (j = k + 1; j < _PB_N; j++)
        Rk[j] = SCALAR_VAL(0.0);

      /* Accumulate the dot products row by row. */
      for (i = 0; i < _PB_M; i++)
      {
        const DATA_TYPE qik = Q[i][k];
        const DATA_TYPE * restrict Ai = A[i];

        /* Each iteration of this inner loop touches different elements
         * Rk[j] and Ai[j], so it is safe to vectorize over j. */
#pragma GCC ivdep
        for (j = k + 1; j < _PB_N; j++)
          Rk[j] += qik * Ai[j];
      }

      /* ------------------------------------------------------------
       * 4) Update A[:, j] = A[:, j] - Q[:,k] * R[k][j] for j > k
       *
       * Original code:
       *   for (j = k+1; j < N; ++j)
       *     for (i = 0; i < M; ++i)
       *       A[i][j] -= Q[i][k] * R[k][j];
       *
       * We again switch to i-outer / j-inner order to:
       *   - traverse A rows contiguously in memory,
       *   - load Q[i][k] once per row and reuse it for all j>k.
       * ------------------------------------------------------------ */
      for (i = 0; i < _PB_M; i++)
      {
        const DATA_TYPE qik = Q[i][k];
        DATA_TYPE * restrict Ai = A[i];

#pragma GCC ivdep
        for (j = k + 1; j < _PB_N; j++)
          Ai[j] -= qik * Rk[j];
      }
    }
#pragma endscop

}


