/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("R");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, R[i][j]);
    }
  POLYBENCH_DUMP_END("R");

  POLYBENCH_DUMP_BEGIN("Q");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, Q[i][j]);
    }
  POLYBENCH_DUMP_END("Q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized version:

   - We create a temporary transposed working copy At of A such that
       At[j * m + i] == A[i][j]
     i.e., each column of A becomes a contiguous row of At.
   - All column-wise operations (norms, dot products, updates) are then
     carried out on At using contiguous memory, which greatly improves
     cache locality and enables efficient vectorization.
   - We overwrite the processed column k in At with the corresponding
     orthonormal vector q_k so that At[k * m + i] holds Q[i][k]. This
     avoids a second temporary array for Q.
   - The algorithmic order of floating-point operations for each scalar
     quantity (nrm, individual R[k][j], and A[i][j] updates) is
     preserved with respect to the original code; only the storage
     layout is changed. Therefore, apart from usual floating-point
     roundoff behavior, the numerical semantics of the original
     algorithm are preserved.
   - At the end we copy the modified matrix back from At to A so that
     the externally visible A matches the original in-place algorithm.
*/
static
void kernel_gramschmidt [[gnu::flatten, gnu::noinline]] (int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE nrm;

  /* Number of elements to allocate for the working copy.
     Use 64-bit size to be robust to larger problem sizes. */
  unsigned long long total_elems =
    (unsigned long long)m * (unsigned long long)n;

  /* Transposed working copy of A:
     At[j * m + i] corresponds to A[i][j]. */
  DATA_TYPE* __restrict__ At =
    (DATA_TYPE*)polybench_alloc_data(total_elems, sizeof(DATA_TYPE));

  /* If allocation fails (very unlikely in the intended setting),
     fall back to the original, unoptimized kernel to preserve
     functional correctness. */
  if (At == NULL)
  {
#pragma scop
    for (k = 0; k < _PB_N; k++)
      {
        nrm = SCALAR_VAL(0.0);
        for (i = 0; i < _PB_M; i++)
          nrm += A[i][k] * A[i][k];
        R[k][k] = SQRT_FUN(nrm);
        for (i = 0; i < _PB_M; i++)
          Q[i][k] = A[i][k] / R[k][k];
        for (j = k + 1; j < _PB_N; j++)
          {
            R[k][j] = SCALAR_VAL(0.0);
            for (i = 0; i < _PB_M; i++)
              R[k][j] += Q[i][k] * A[i][j];
            for (i = 0; i < _PB_M; i++)
              A[i][j] = A[i][j] - Q[i][k] * R[k][j];
          }
      }
#pragma endscop
    return;
  }

  /* Build the transposed working copy At from A.
     This is O(m*n), which is negligible compared to the O(m*n^2)
     cost of the Gram-Schmidt algorithm itself for typical sizes. */
  for (j = 0; j < n; j++)
  {
    size_t base_j = (size_t)j * (size_t)m;
    for (i = 0; i < m; i++)
      At[base_j + (size_t)i] = A[i][j];
  }

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      size_t base_k = (size_t)k * (size_t)m;

      /* 1. Compute the 2-norm of the k-th column of the current A,
            using the contiguous vector At[k][:]. */
      nrm = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_M; i++)
      {
        DATA_TYPE val = At[base_k + (size_t)i];
        nrm += val * val;
      }

      /* Diagonal entry of R. */
      DATA_TYPE rkk = SQRT_FUN(nrm);
      R[k][k] = rkk;

      /* Precompute reciprocal to replace divisions by multiplications. */
      DATA_TYPE invRkk = SCALAR_VAL(1.0) / rkk;

      /* 2. Normalise the k-th column to form q_k.
            Store q_k in-place in At[k][:] and also in the output Q. */
      for (i = 0; i < _PB_M; i++)
      {
        DATA_TYPE qki = At[base_k + (size_t)i] * invRkk;
        At[base_k + (size_t)i] = qki;  /* Now At holds Q_k in row k */
        Q[i][k] = qki;                 /* Row-major view for output */
      }

      /* 3. For each remaining column j > k, compute R[k][j] and
            orthogonalize that column against q_k.

         This loop structure (j outer, then i inner) matches the
         original algorithm's order of operations for each R[k][j]
         and A[i][j], but now both q_k and a_j are accessed through
         contiguous slices of At, enabling good cache use and
         vectorization. */
      for (j = k + 1; j < _PB_N; j++)
      {
        size_t base_j = (size_t)j * (size_t)m;

        /* Dot product r_kj = q_k^T * a_j. */
        DATA_TYPE rkj = SCALAR_VAL(0.0);
        for (i = 0; i < _PB_M; i++)
