static
void kernel_gramschmidt [[gnu::flatten, gnu::noinline]] (int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE nrm;

  /* Create local restrict-qualified views of the 2D arrays.
     Using 'n' (the runtime leading dimension) keeps the correct VLA type.
     The restrict qualifiers tell the compiler that A_, R_, and Q_ do not
     alias each other, enabling better vectorization. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict R_)[n] = R;
  DATA_TYPE (*restrict Q_)[n] = Q;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
