      nrm = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_M; i++)
      {
        DATA_TYPE aik = A_[i][k];
        nrm += aik * aik;
      }

      DATA_TYPE Rkk = SQRT_FUN(nrm);
      R_[k][k] = Rkk;

      /* Replace many divisions by a single division and multiplies:
         Q[:,k] = A[:,k] / Rkk = A[:,k] * (1 / Rkk). */
      const DATA_TYPE inv_Rkk = SCALAR_VAL(1.0) / Rkk;

      /* 2) Normalize column k: compute Q[:,k]. */
      for (i = 0; i < _PB_M; i++)
      {
        Q_[i][k] = A_[i][k] * inv_Rkk;
      }

      /* 3) For columns j > k, compute R[k][j] and update A[:,j].
         We reorganize the loops to improve data locality:

           - Original code:
               for j>k:  (column-wise, strided access in memory)
                 R[k][j] = dot(Q[:,k], A[:,j])
                 A[:,j] -= Q[:,k] * R[k][j]

           - New code (semantics-preserving):
               a) Zero-initialize R[k][j] once for all j>k.
               b) Compute all dot products R[k][j] with
                  outer loop on 'i' and inner loop on 'j',
                  giving contiguous row-wise accesses.
               c) Update A in a separate set of loops, also
                  with inner loop on 'j' for better cache use.

         For each fixed (k,j), the reduction over 'i' is performed in the
         same order as in the original code (i = 0.._PB_M-1), so the
         floating-point evaluation order and thus the numerical semantics
         are preserved. */
      if (k + 1 < _PB_N)
      {
        /* a) Initialize R[k][j] = 0 for all j > k. */
        for (j = k + 1; j < _PB_N; j++)
          R_[k][j] = SCALAR_VAL(0.0);

        /* b) Compute R[k][j] = sum_i Q[i][k] * A[i][j] for all j > k.

           Outer loop on rows 'i' gives:
             - Q_[i][k] is reused across many j.
             - A_[i][j] and R_[k][j] are accessed with unit stride in 'j',
               which is cache- and SIMD-friendly. */
        for (i = 0; i < _PB_M; i++)
        {
          const DATA_TYPE qik = Q_[i][k];
          const DATA_TYPE *restrict Ai = A_[i];
          DATA_TYPE *restrict Rk = R_[k];

          for (j = k + 1; j < _PB_N; j++)
          {
            Rk[j] += qik * Ai[j];
          }
        }

        /* c) Update A[:,j] = A[:,j] - Q[:,k] * R[k][j] for all j > k.

           Again, we use row-wise (i outer, j inner) traversal for
           contiguous memory access in the inner loop. All updates to
           A[i][j] are independent across (i,j), so this reordering
           preserves the original semantics. */
        for (i = 0; i < _PB_M; i++)
        {
          const DATA_TYPE qik = Q_[i][k];
          DATA_TYPE *restrict Ai = A_[i];
          const DATA_TYPE *restrict Rk = R_[k];

          for (j = k + 1; j < _PB_N; j++)
          {
            Ai[j] -= qik * Rk[j];
          }
        }
      }
    }
#pragma endscop

